  if (typeof args === 'string') {
    try { args = JSON.parse(args); }
    catch (e) { throw new Error('W0: "args" no es JSON válido: ' + args); }
  }
  out.push({ json: { op: String(src.op), args, _via: porWebhook ? 'webhook' : 'subworkflow' } });
}
return out;

